  return items.map(item => ({ item, score: fuzzyScore(query, getName(item)) }))
    .filter(x => x.score > 0)
    .sort((a, b) => b.score - a.score || getName(a.item).localeCompare(getName(b.item)))
    .slice(0, limit)
