  async function handleMarkComplete() {
    if (!localTask || localTask.status === 'Done') return
    await handleStatusChange('Done')
  }

  // ── Render ───────────────────────────────────────────────────────────────
  if (loading) return <DetailSkeleton />

  if (notFound || !localTask) {
    return (
      <div className="not-found-panel">
