    return (
      <div className="signal-card signal-card--retracted" data-signal-id={signal.id}>
        <p className="signal-tombstone">
          {t('signals.retracted')} {signal.retract_reason ? <span>{signal.retract_reason}</span> : null}
        </p>
      </div>
