text:
/* SignalCard — the posted-Signal card (PORT convergence `sigCard` @ the e7 visual bar,
   design-review step-4 CRITICAL-1/2). Card boundary + padding + rhythm: avatar chip · name ·
   time · attention pill; body; meta pills; visibility line; the action row. Every color/radius/
   shadow resolves to a DESIGN.md --ds-*, --brand-*, or --status-* token — no --e7-* names, no
   raw hex (docs/reviews/design-authority-audit-2026-07-17.md). */

.signal-card {
  padding: 16px;
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-rest);
}
.signal-card + .signal-card { margin-top: 12px; }

/* A retracted Signal renders only the tombstone (D31) — quieter frame, no body/actions. */
.signal-card--retracted { padding: 12px 16px; }
.signal-tombstone {
  margin: 0; font-size: 13px; color: var(--muted-foreground); font-style: italic;
}
.signal-tombstone span { margin-left: 6px; }

.signal-head { display: flex; align-items: center; gap: 8px; margin-bottom: 6px; }
/* VIS-1 canonical avatar gradient (navy→primary, OD-P3-7) — same as shell/UserChip.tsx and
   TaskSurface.css .person-av. Violet stays KPI/timeline-only; no avatar carries it. */
.signal-avatar {
  width: 28px; height: 28px; border-radius: var(--radius-pill); flex: none;
  display: inline-flex; align-items: center; justify-content: center;
  font-weight: 700; font-size: 12px; color: var(--primary-foreground);
  background: linear-gradient(135deg, var(--brand-navy), var(--primary));
}
.signal-who { font-weight: 600; font-size: 13.5px; color: var(--foreground); }
.signal-when { font-size: 12px; color: var(--muted-foreground); }

/* ── Attention weight (CRITICAL-2) — Tinted-Status pattern (DESIGN.md §Tinted-Status):
   Urgent = destructive family, Needs attention = warning family, FYI = neutral. ── */
.signal-attention {
  margin-left: auto; flex: none; display: inline-flex; align-items: center;
  height: 22px; padding: 0 9px; border-radius: var(--radius-pill);
  font-size: 12px; font-weight: 600; white-space: nowrap;
}
.signal-attention--urgent {
  background: color-mix(in srgb, var(--destructive) 12%, transparent);
  color: var(--status-lost-text);
}
.signal-attention--needs-attention {
  background: color-mix(in srgb, var(--warning) 18%, transparent);
  color: var(--warning-foreground);
}
.signal-attention--fyi {
  background: var(--secondary);
  color: var(--muted-foreground);
}

.signal-body { font-size: 14px; line-height: 1.5; color: var(--foreground); }
.signal-body-link {
  display: block; width: 100%; text-align: left; background: none; border: none;
  padding: 0; font: inherit; color: inherit; cursor: pointer;
}
.signal-body-link:hover { text-decoration: underline; }
.signal-body-link:focus-visible { outline: 2px solid var(--ring); outline-offset: 2px; border-radius: var(--radius-xs); }

.signal-meta { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; margin-top: 10px; }
.signal-meta-pill {
  display: inline-flex; align-items: center; height: 22px; padding: 0 8px;
  border-radius: var(--radius-pill); background: var(--secondary); color: var(--muted-foreground);
  font-size: 11.5px;
}

.signal-vis { display: block; font-size: 11.5px; color: var(--muted-foreground); margin-top: 8px; }

.signal-actions {
  display: flex; align-items: center; gap: 8px; flex-wrap: wrap;
  margin-top: 12px; padding-top: 10px;
  border-top: 1px solid color-mix(in srgb, var(--border) 70%, transparent);
}
.signal-actions-spacer { flex: 1; }

/* ── The shared category picker anchor + popover (also used from signal-record.tsx) ── */
.signal-category-picker-anchor { position: relative; display: inline-flex; }
.signal-category-pill {
  display: inline-flex; align-items: center; height: 22px; padding: 0 9px;
  border-radius: var(--radius-pill); background: var(--secondary); color: var(--muted-foreground);
  font-size: 12px; font-weight: 600;
}
.signal-category-picker {
  position: absolute; top: 100%; left: 0; margin-top: 4px; z-index: 50;
  min-width: 200px; background: var(--card); border: 1px solid var(--border);
  border-radius: var(--radius-lg); box-shadow: var(--shadow-overlay); padding: 4px;
}
.signal-category-option {
  display: block; width: 100%; text-align: left; padding: 8px 10px;
  border: none; background: none; font: inherit; color: var(--foreground);
  border-radius: var(--radius-sm); cursor: pointer; font-size: 13px; min-height: 36px;
}
.signal-category-option:hover { background: var(--secondary); }
.signal-category-option[aria-selected="true"] {
  background: var(--accent-subtle); color: var(--text-accent); font-weight: 600;
}

