  1	/* SignalComposer — the FB-style capture-minimal panel (PORT convergence `sigComposer` @ the
  2	   e7 visual bar, design-review step-4 CRITICAL-1). Panel padding + vertical rhythm, labeled
  3	   fields with real space between label and value (MINOR-7/8), and a bordered foot row. */
  4	.signal-composer {
  5	  display: flex; flex-direction: column; gap: 12px; padding: 16px;
  6	}
  7	
  8	/* The composer's mention popover anchors to the textarea, so the wrapper is the positioning
  9	   context for the absolutely-positioned SignalMentionPicker (replaces an inline style — house
 10	   pattern is a class in a co-located stylesheet). */
 11	.signal-composer-mention-anchor {
 12	  position: relative;
 13	}
 14	.signal-composer-mention-anchor textarea {
 15	  width: 100%; min-height: 96px; padding: 12px;
 16	  border: 1px solid var(--border); border-radius: var(--radius-lg);
 17	  background: var(--card); font: inherit; font-size: 14px; color: var(--foreground);
 18	  resize: vertical; line-height: 1.5;
 19	}
 20	.signal-composer-mention-anchor textarea::placeholder { color: var(--text-light); }
 21	.signal-composer-mention-anchor textarea:focus-visible {
 22	  outline: 2px solid var(--ring); outline-offset: 1px; border-radius: var(--radius-lg);
 23	}
 24	
 25	.signal-composer-row { display: flex; align-items: flex-start; gap: 12px; flex-wrap: wrap; }
 26	.signal-composer-row > * { flex: 1; min-width: 180px; }
 27	
 28	/* datetime-local has no equivalent styled kit primitive (TextInput/Select), so the label +
 29	   box are styled directly here — mirrors the kit's own label-above-box rhythm (Select.css). */
 30	.signal-composer-datetime { display: flex; flex-direction: column; gap: 4px; }
 31	.signal-composer-field-label {
 32	  font-size: 12px; color: var(--muted-foreground); font-weight: 500;
 33	}
 34	.signal-composer-datetime input {
 35	  display: block; width: 100%; height: 32px; padding: 0 10px; box-sizing: border-box;
 36	  background: var(--background); border: 1px solid var(--input);
 37	  border-radius: var(--radius-sm); font: inherit; font-size: 15px; color: var(--foreground);
 38	}
 39	.signal-composer-datetime input:focus-visible {
 40	  outline: 2px solid var(--ring); outline-offset: 2px;
 41	}
 42	
 43	.signal-composer-pill {
 44	  display: inline-flex; align-items: center; gap: 5px; height: 24px; padding: 0 8px;
 45	  border-radius: var(--radius-pill); background: var(--secondary); color: var(--muted-foreground);
 46	  font-size: 11.5px; width: fit-content;
 47	}
 48	
 49	.signal-composer-author,
 50	.signal-composer-vis {
 51	  margin: 0; font-size: 12px; color: var(--muted-foreground);
 52	}
 53	
 54	.signal-composer-foot {
 55	  display: flex; align-items: center; gap: 8px; padding-top: 12px;
 56	  border-top: 1px solid color-mix(in srgb, var(--border) 70%, transparent);
 57	}
 58	.signal-composer-foot .muted-2 { flex: 1; min-width: 0; font-size: 12px; color: var(--muted-foreground); }

