  1	import { useCallback, useSyncExternalStore } from 'react'
  2	
  3	// ── Keys ────────────────────────────────────────────────────────────────────
  4	// 'mos.tasks.view' is reserved for forward-compat (Board/Calendar are stubs);
  5	// only 'table' is valid in v1, so view is not persisted/read here.
  6	const KEY_GROUP_BY = 'mos.tasks.groupBy'
  7	const KEY_COLLAPSED = 'mos.tasks.collapsedGroups'
  8	
  9	// ── Types ────────────────────────────────────────────────────────────────────
 10	// 'none' = a FLAT, ungrouped list (the signed mockup default — mock-shell-and-table.html
 11	// is not status-grouped). status/owner/bu/workline remain available via the Group chip.
 12	// Step 6 (ADR-0051 D9/D10, C1): 'occurrence' groups generated Tasks under their run's caption
 13	// (never the internal-only string "Process Run" — FR-611).
 14	export type TasksGroupBy = 'none' | 'status' | 'owner' | 'bu' | 'workline' | 'occurrence'
 15	export type TasksView = 'table'
 16	
 17	export interface TasksViewPref {
 18	  view: TasksView
 19	  groupBy: TasksGroupBy
 20	  collapsedGroups: Partial<Record<TasksGroupBy, string[]>>
 21	  setGroupBy: (g: TasksGroupBy) => void
 22	  /** Toggles the given groupKey under the current groupBy dimension. */
 23	  toggleCollapsed: (groupKey: string) => void
 24	  /** Returns true if groupKey is currently collapsed under the current groupBy. */
 25	  isCollapsed: (groupKey: string) => boolean
 26	}
 27	
 28	// ── Storage helpers (guarded try/catch for SSR / privacy-mode) ──────────────
 29	
 30	const VALID_GROUP_BY: TasksGroupBy[] = ['none', 'status', 'owner', 'bu', 'workline', 'occurrence']
 31	
 32	function readView(): TasksView {
 33	  // Only 'table' is valid in v1 (Board/Calendar are stubs); the stored value is
 34	  // read so the key exists for forward-compat, but it always resolves to 'table'.
 35	  return 'table'
 36	}
 37	
 38	function readGroupBy(): TasksGroupBy {
 39	  try {
 40	    const v = localStorage.getItem(KEY_GROUP_BY) as TasksGroupBy | null
 41	    // Default = 'none' (FLAT) to match the signed mockup; grouping is opt-in via the chip.
 42	    return v && VALID_GROUP_BY.includes(v) ? v : 'none'
 43	  } catch {
 44	    return 'none'
 45	  }
 46	}
 47	
 48	function readCollapsed(): Partial<Record<TasksGroupBy, string[]>> {
 49	  try {
 50	    const raw = localStorage.getItem(KEY_COLLAPSED)
 51	    if (!raw) return {}
 52	    const parsed = JSON.parse(raw)
 53	    if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) return {}
 54	    // Validate: keep only valid TasksGroupBy keys with string[] values
 55	    const result: Partial<Record<TasksGroupBy, string[]>> = {}
 56	    for (const key of VALID_GROUP_BY) {
 57	      if (Array.isArray(parsed[key])) {
 58	        result[key] = (parsed[key] as unknown[]).filter((v): v is string => typeof v === 'string')
 59	      }
 60	    }
 61	    return result
 62	  } catch {
 63	    return {}
 64	  }
 65	}
 66	
 67	// ── Module-level shared store (mirrors useExpandPref's C1 pattern exactly) ──
 68	// Single source of truth: one snapshot + subscriber set so all consumers
 69	// share ONE source and re-render together on change.
 70	
 71	interface StoreSnapshot {
 72	  view: TasksView
 73	  groupBy: TasksGroupBy
 74	  collapsedGroups: Partial<Record<TasksGroupBy, string[]>>
 75	}
 76	
 77	const subscribers = new Set<() => void>()
 78	let snapshot: StoreSnapshot = {
 79	  view: readView(),
 80	  groupBy: readGroupBy(),
 81	  collapsedGroups: readCollapsed(),
 82	}
 83	
 84	function subscribe(cb: () => void): () => void {
 85	  subscribers.add(cb)
 86	  return () => { subscribers.delete(cb) }
 87	}
 88	
 89	function getSnapshot(): StoreSnapshot {
 90	  return snapshot
 91	}
 92	
 93	function notify() {
 94	  for (const cb of subscribers) cb()
 95	}
 96	
 97	function setGroupByStore(g: TasksGroupBy) {
 98	  if (snapshot.groupBy === g) return
 99	  snapshot = { ...snapshot, groupBy: g }
100	  try { localStorage.setItem(KEY_GROUP_BY, g) } catch { /* storage disabled */ }
101	  notify()
102	}
103	
104	function toggleCollapsedStore(groupKey: string, currentGroupBy: TasksGroupBy) {
105	  const existing = snapshot.collapsedGroups[currentGroupBy] ?? []
106	  const next = existing.includes(groupKey)
107	    ? existing.filter(k => k !== groupKey)
108	    : [...existing, groupKey]
109	  const nextCollapsed = { ...snapshot.collapsedGroups, [currentGroupBy]: next }
110	  snapshot = { ...snapshot, collapsedGroups: nextCollapsed }
111	  try { localStorage.setItem(KEY_COLLAPSED, JSON.stringify(nextCollapsed)) } catch { /* storage disabled */ }
112	  notify()
113	}
114	
115	/**
116	 * Per-user-global persistence for Tasks view preferences (FR-125, AC-127).
117	 * Mirrors useExpandPref's useSyncExternalStore-over-localStorage module pattern verbatim.
118	 * Keys: mos.tasks.view, mos.tasks.groupBy, mos.tasks.collapsedGroups.
119	 */
120	export function useTasksViewPref(): TasksViewPref {
121	  const { view, groupBy, collapsedGroups } = useSyncExternalStore(subscribe, getSnapshot, getSnapshot)
122	
123	  const setGroupBy = useCallback((g: TasksGroupBy) => {
124	    setGroupByStore(g)
125	  }, [])
126	
127	  const toggleCollapsed = useCallback((groupKey: string) => {
128	    toggleCollapsedStore(groupKey, snapshot.groupBy)
129	  }, [])
130	
131	  const isCollapsed = useCallback((groupKey: string) => {
132	    const collapsed = snapshot.collapsedGroups[snapshot.groupBy] ?? []
133	    return collapsed.includes(groupKey)
134	  }, [])
135	
136	  return { view, groupBy, collapsedGroups, setGroupBy, toggleCollapsed, isCollapsed }
137	}
138	
139	/**
140	 * Test-only reset: clears in-memory snapshot back to what localStorage holds.
141	 * Call after localStorage.clear() in test setup so the shared module state
142	 * doesn't leak between test cases.
143	 */
144	export function __resetTasksViewPrefForTests() {
145	  snapshot = {
135	  // Step 7 (cafe-retrofit.spec.md FR-704, C2): a host link (e.g. the Café panel's "View opening
136	  // tasks") can arrive with ?occurrence=<runId> to land directly on the Occurrence grouping — REUSES
137	  // the Step-6 occurrence group-by (Rule 11), no new grouping/scoping mechanism. One-shot on mount
138	  // (a later manual Group change is never fought back to Occurrence).
139	  const [searchParams] = useSearchParams()
140	  useEffect(() => {
141	    if (searchParams.has('occurrence')) setGroupBy('occurrence')
142	    // eslint-disable-next-line react-hooks/exhaustive-deps -- one-shot on the param's initial presence
143	  }, [])
144	
145	  // ── Filters ────────────────────────────────────────────────────────────────
146	  const [businessUnitId, setBusinessUnitId] = useState<string>('')
147	  const [statusFilter, setStatusFilter] = useState<TaskStatus | ''>('')
148	  const [includeArchived, setIncludeArchived] = useState(false)
149	  const [segment, setSegment] = useState<Segment>(savedView?.segment ?? 'all')
150	  const [personFilter, setPersonFilter] = useState<string>('')
151	  const [searchText, setSearchText] = useState<string>('')
152	  const [mobileOptionsOpen, setMobileOptionsOpen] = useState(false)
153	  // Transient overdue-only filter (AC-128 / FR-126) — clicking "N overdue" sets this;
154	  // cleared via the chip ✕ or the Clear filters button.
155	  const [overdueOnly, setOverdueOnly] = useState(savedView?.overdueOnly ?? false)
