125	  }, [])
126	
127	  const toggleCollapsed = useCallback((groupKey: string) => {
128	    toggleCollapsedStore(groupKey, snapshot.groupBy)
129	  }, [])
130	
131	  const isCollapsed = useCallback((groupKey: string) => {
132	    const collapsed = snapshot.collapsedGroups[snapshot.groupBy] ?? []
133	    return collapsed.includes(groupKey)
134	  }, [])
135	
136	  return { view, groupBy, collapsedGroups, setGroupBy, toggleCollapsed, isCollapsed }
137	}
